INSERT INTO public.procedures (title, slug, short_description, description, category_id, scope, cost, estimated_duration, source, source_url, is_published, verification_status, last_verified_at)
SELECT v.title, v.slug, v.short_description, v.descr, c.id, v.scope, v.cost, v.duration, 'Trami España (contenido verificado)', v.url, true, 'verified', now()
FROM (VALUES
    ('Primera expedición del Documento Nacional de Identidad (DNI)', 'primera-expedicion-dni', 'Tramita por primera vez tu DNI: cita previa, documentación necesaria y tasas.', 'El DNI es el documento oficial que acredita la identidad y la nacionalidad española. La primera expedición debe realizarse en persona en una oficina de expedición, previa cita, y se entrega en el mismo acto. Obligatorio a partir de los 14 años.', 'identidad', 'estatal', '12,30 € (tasa)', '1 hora (con cita previa)', 'https://www.dnielectronico.es'),
    ('Expedición y renovación del pasaporte ordinario', 'expedicion-pasaporte', 'Obtén o renueva tu pasaporte ordinario: requisitos, cita previa y tasa vigente.', 'El pasaporte ordinario es el documento que acredita la identidad y nacionalidad española fuera del país. Se expide en oficinas de expedición (comisarías) con cita previa y tiene una vigencia de 10 años para adultos.', 'identidad', 'estatal', '30 € (tasa)', '45 minutos (con cita previa)', 'https://www.policia.es'),
    ('Registro y activación de Cl@ve (sistema de identificación)', 'registro-clave', 'Date de alta en Cl@ve, el sistema público de identificación para trámites online.', 'Cl@ve es la plataforma común de identificación, autenticación y firma electrónica de las administraciones públicas españolas. Permite realizar trámites online con una única cuenta mediante Cl@ve PIN o Cl@ve Permanente.', 'identidad', 'estatal', 'Gratuito', '10 minutos', 'https://clave.gob.es'),
    ('Certificado digital de persona física (FNMT)', 'certificado-digital-fnmt', 'Solicita tu certificado digital FNMT para firmar y realizar trámites online.', 'El certificado digital de la Fábrica Nacional de Moneda y Timbre (FNMT) identifica a la persona física en sus relaciones con las administraciones públicas y entidades privadas, permitiendo firmar electrónicamente cualquier trámite.', 'identidad', 'estatal', 'Gratuito', '2 días hábiles (solicitud y acreditación)', 'https://www.sede.fnmt.gob.es'),
    ('Renovación del empadronamiento municipal', 'renovacion-empadronamiento', 'Renueva periódicamente tu inscripción en el padrón municipal de habitantes.', 'Los extranjeros no comunitarios sin autorización de residencia permanente deben renovar su inscripción padronal cada 2 años. Si no se renueva en plazo, el Ayuntamiento puede dar de baja la inscripción y se pierden derechos vinculados.', 'empadronamiento', 'estatal', 'Gratuito', '20 minutos', 'https://administracion.gob.es/pag_Home/ciudadanos/queNecesitoHago/Documento-empadronamiento.html'),
    ('Cambio de domicilio en el padrón municipal', 'cambio-domicilio-empadronamiento', 'Actualiza tu empadronamiento al cambiar de vivienda dentro o fuera del municipio.', 'Todo ciudadano debe empadronarse en el municipio donde resida habitualmente. Al mudarte, comunica el cambio de domicilio para que conste tu dirección actual y puedas ejercer derechos como sanidad, escolarización o votar en tu nueva circunscripción.', 'empadronamiento', 'estatal', 'Gratuito', '20 minutos', 'https://administracion.gob.es/pag_Home/ciudadanos/queNecesitoHago/Documento-empadronamiento.html'),
    ('Certificado de empadronamiento', 'certificado-empadronamiento', 'Solicita el certificado oficial que acredita tu empadronamiento y antigüedad.', 'El certificado de empadronamiento acredita oficialmente tu inscripción en el padrón, la dirección habitual y la antigüedad de residencia. Es imprescindible para trámites de extranjería, matrimonio, escolarización o compra de vehículos.', 'empadronamiento', 'estatal', 'Gratuito', '15 minutos (o por correo en 5 días)', 'https://administracion.gob.es/pag_Home/ciudadanos/queNecesitoHago/Documento-empadronamiento.html'),
    ('Volante de empadronamiento', 'volante-empadronamiento', 'Obtén el volante informativo de empadronamiento, rápido y sin coste.', 'El volante de empadronamiento es un documento informativo que refleja los datos de la inscripción padronal. A diferencia del certificado, no tiene carácter formal documental, pero sirve para trámites administrativos generales y se expide al instante.', 'empadronamiento', 'estatal', 'Gratuito', '10 minutos', 'https://administracion.gob.es/pag_Home/ciudadanos/queNecesitoHago/Documento-empadronamiento.html'),
    ('Empadronamiento de menores de edad', 'empadronamiento-menores', 'Inscribe a un menor en el padrón municipal: documentación y pasos a seguir.', 'Los menores deben estar empadronados en el domicilio de sus padres o tutores. Es necesario para la escolarización, la tarjeta sanitaria y las prestaciones familiares, y puede realizarse en el mismo acto que el alta de los padres.', 'empadronamiento', 'estatal', 'Gratuito', '20 minutos', 'https://administracion.gob.es/pag_Home/ciudadanos/queNecesitoHago/Documento-empadronamiento.html'),
    ('Solicitud del informe de Vida Laboral', 'vida-laboral', 'Descarga tu informe de vida laboral: historial completo de cotizaciones a la SS.', 'La vida laboral es un documento oficial de la Seguridad Social que recoge todas las empresas en las que has trabajado y las fechas de alta y baja. Es imprescindible para calcular jubilaciones, solicitar ayudas o acreditar experiencia.', 'laboral', 'estatal', 'Gratuito', '5 minutos', 'https://sede.administracionespublicas.gob.es/pagFront/indexInformacionVidaLaboral'),
    ('Inscripción como demandante de empleo', 'inscripcion-demandante-empleo', 'Date de alta como demandante de empleo y accede a ofertas y prestaciones.', 'La inscripción como demandante de empleo («carné de paro») permite acceder a ofertas de los servicios públicos de empleo y es requisito previo para cobrar el desempleo. Debe renovarse periódicamente para mantener el alta.', 'laboral', 'estatal', 'Gratuito', '30 minutos', 'https://sede.sepe.gob.es'),
    ('Subsidio para mayores de 52 años', 'subsidio-mayores-52-anos', 'Solicita el subsidio del SEPE para desempleados mayores de 52 años.', 'El subsidio para mayores de 52 años es una prestación asistencial del SEPE para quienes han agotado su prestación contributiva. Mientras se percibe, la Seguridad Social cotiza para la jubilación al 125 % de la base mínima.', 'laboral', 'estatal', 'Gratuito', '20 minutos', 'https://sede.sepe.gob.es'),
    ('Subsidio por desempleo (agotamiento de la prestación)', 'subsidio-desempleo-agotamiento', 'Pide el subsidio asistencial al agotar tu prestación contributiva de desempleo.', 'El subsidio por desempleo es la prestación asistencial que se solicita al agotar el paro contributivo o en otras causas reconocidas (responsabilidades familiares, mayores de 45 años). Requiere carencia de rentas y estar inscrito como demandante.', 'laboral', 'estatal', 'Gratuito', '20 minutos', 'https://sede.sepe.gob.es'),
    ('Baja médica por incapacidad temporal (IT)', 'baja-medica-incapacidad-temporal', 'Gestiona tu baja médica: expedición, seguimiento y alta de la incapacidad temporal.', 'La incapacidad temporal es la situación del trabajador temporalmente imposibilitado para trabajar por enfermedad común, accidente o maternidad. Los partes de baja, confirmación y alta determinan el cobro del subsidio correspondiente durante la ausencia.', 'laboral', 'estatal', 'Gratuito', '15 minutos', 'https://sede.seg-social.gob.es'),
    ('Solicitud de la Tarjeta Sanitaria Europea (TSE)', 'tarjeta-sanitaria-europea', 'Pide la Tarjeta Sanitaria Europea para recibir asistencia médica en la UE.', 'La Tarjeta Sanitaria Europea garantiza la atención médica necesaria durante estancias temporales en la Unión Europea, Espacio Económico Europeo y Suiza, en las mismas condiciones que los asegurados del país visitado.', 'seguridad-social', 'estatal', 'Gratuito', '15 minutos (envío en 10 días)', 'https://sede.inss.gob.es'),
    ('Solicitud de la pensión de jubilación contributiva', 'pension-jubilacion', 'Solicita tu pensión de jubilación ante el INSS: requisitos y plazos clave.', 'La pensión de jubilación contributiva es la prestación económica vitalicia que reconoce la Seguridad Social a quienes alcanzan la edad legal de jubilación y acreditan el periodo mínimo de cotización. Se solicita hasta 3 meses antes de la fecha prevista.', 'seguridad-social', 'estatal', 'Gratuito', '20 minutos', 'https://sede.seg-social.gob.es'),
    ('Reconocimiento de la situación de dependencia (Ley de Dependencia)', 'dependencia-valoracion', 'Solicita la valoración del grado de dependencia y accede a ayudas y servicios.', 'La Ley de Dependencia reconoce derechos a las personas que necesitan ayuda para las actividades básicas de la vida diaria. Tras la solicitud, un equipo de valoración determina el grado y nivel, que abre el acceso a servicios y prestaciones económicas.', 'seguridad-social', 'estatal', 'Gratuito', '30 minutos (resolución en meses según CCAA)', 'https://imserso.es'),
    ('Solicitud de la incapacidad permanente ante el INSS', 'incapacidad-permanente', 'Solicita la incapacidad permanente: grados, documentación y evaluación médica.', 'La incapacidad permanente es la prestación que reconoce la Seguridad Social cuando, tras tratarse una lesión o enfermedad, quedan secuelas reductoras de la capacidad laboral. Se determina tras la evaluación por el tribunal médico (EVI).', 'seguridad-social', 'estatal', 'Gratuito', '30 minutos', 'https://sede.seg-social.gob.es'),
    ('Solicitud del Ingreso Mínimo Vital (IMV)', 'ingreso-minimo-vital', 'Pide el Ingreso Mínimo Vital: renta mínima estatal para unidades familiares.', 'El Ingreso Mínimo Vital es una prestación de la Seguridad Social que garantiza unos ingresos mínimos a las unidades de convivencia en situación de vulnerabilidad económica. La cuantía depende de los ingresos y del número de miembros del hogar.', 'seguridad-social', 'estatal', 'Gratuito', '30 minutos', 'https://sede.seg-social.gob.es'),
    ('Prestación por nacimiento o adopción de hijo', 'prestacion-nacimiento-adopcion', 'Solicita la prestación económica por nacimiento, adopción o acogimiento.', 'La prestación por nacimiento o adopción es un pago único a cargo de la Seguridad Social (el «cheque bebé»), abonado por cada hijo nacido o adoptado. También existen las prestaciones de maternidad y paternidad por suspensión de actividad.', 'seguridad-social', 'estatal', 'Gratuito', '15 minutos', 'https://sede.seg-social.gob.es'),
    ('Inscripción de nacimiento en el Registro Civil', 'inscripcion-nacimiento-registro-civil', 'Inscribe a tu hijo en el Registro Civil: plazos y documentación necesaria.', 'La inscripción de nacimiento es el acto que oficializa la existencia de una persona y determina su filiación. Debe realizarse en el Registro Civil del lugar de nacimiento en un plazo máximo de 8 días (o 30 si se justifica).', 'familia', 'estatal', 'Gratuito', '30 minutos', 'https://sede.mjusticia.gob.es'),
    ('Solicitud del libro de familia (o libreta)', 'libro-familia', 'Tramita el libro de familia o solicita la sustitución por certificados digitales.', 'El libro de familia es el documento tradicional que acredita el estado civil y las relaciones familiares. Desde 2021, los recién nacidos ya no reciben libreta: se sustituye por certificados electrónicos, aunque sigue siendo posible obtenerla o renovarla.', 'familia', 'estatal', 'Gratuito', '20 minutos', 'https://sede.mjusticia.gob.es'),
    ('Título de familia numerosa', 'titulo-familia-numerosa', 'Solicita el título de familia numerosa y sus descuentos y beneficios.', 'El título de familia numerosa acredita la condición de familia numerosa (general o especial) y da derecho a beneficios fiscales, educativos, de transporte y laboral. Lo expide la comunidad autónoma y tiene validez en todo el territorio nacional.', 'familia', 'estatal', 'Gratuito', '30 minutos (resolución en meses)', 'https://administracion.gob.es'),
    ('Reconocimiento del grado de discapacidad (33 % o superior)', 'grado-discapacidad', 'Solicita la valoración del grado de discapacidad y sus beneficios asociados.', 'El reconocimiento del grado de discapacidad (mínimo 33 %) acredita oficialmente la situación y da acceso a prestaciones, exenciones fiscales, empleos reservados y ayudas. La valoración la realizan los equipos de valoración y orientación (EVO) autonómicos.', 'familia', 'estatal', 'Gratuito', '30 minutos', 'https://imserso.es'),
    ('Prestación por hijo a cargo (Seguridad Social)', 'prestacion-hijo-cargo', 'Solicita la asignación económica por hijo a cargo de la Seguridad Social.', 'La asignación por hijo a cargo es una prestación mensual de la Seguridad Social para familias con hijos menores de 18 años o con discapacidad igual o superior al 18 %, siempre que los ingresos de la unidad familiar no superen el límite legal.', 'familia', 'estatal', 'Gratuito', '15 minutos', 'https://sede.seg-social.gob.es'),
    ('Autorización de viaje para menores de edad', 'autorizacion-viaje-menores', 'Tramita el consentimiento y la autorización de viaje de menores al extranjero.', 'Los menores de edad que viajen fuera de España sin sus padres o con una sola persona adulta autorizada pueden necesitar una autorización de viaje o consentimiento expreso, tramitada ante notario, comisaría o de forma electrónica según el destino.', 'familia', 'estatal', 'Aprox. 30-60 € (notarial) o gratuito (policial)', '30 minutos', 'https://www.policia.es'),
    ('Renovación del permiso de conducción', 'renovacion-permiso-conducir', 'Renueva tu permiso de conducir: psicotécnico, tasas y cita en la DGT o centros.', 'El permiso de conducir debe renovarse periódicamente según la edad y las condiciones psicofísicas del titular. La renovación puede tramitarse en centros de reconocimiento de conductores o en las oficinas de la DGT, con el informe de aptitud psicofísica.', 'vehiculos', 'estatal', '24,10 € (tasa 4.1) + informe médico', '30 minutos', 'https://sede.dgt.gob.es'),
    ('Cambio de titularidad de un vehículo', 'cambio-titularidad-vehiculo', 'Cambia la titularidad de un vehículo comprado o vendido ante la DGT.', 'La transmisión de un vehículo exige inscribir el cambio de titularidad en la Jefatura Provincial de Tráfico (o en la sede electrónica de la DGT) en un plazo de 30 días desde la venta, para que el comprador figure como nuevo propietario.', 'vehiculos', 'estatal', '54,60 € (tasa 4.1)', '30 minutos', 'https://sede.dgt.gob.es'),
    ('Matriculación de un vehículo nuevo', 'matriculacion-vehiculo', 'Matricula tu vehículo nuevo: tasas, documentación y primera ITV obligatoria.', 'La matriculación es el trámite que asigna la matrícula y habilita la circulación del vehículo. Requiere el certificado de conformidad, el abono de la tasa DGT y, salvo exenciones, el IEDMT (impuesto de matriculación) cuando proceda.', 'vehiculos', 'estatal', '99,80 € (tasa 4.1)', '45 minutos', 'https://sede.dgt.gob.es'),
    ('Baja temporal o definitiva de un vehículo', 'baja-vehiculo', 'Da de baja tu vehículo: temporal por no circular o definitiva por desguace.', 'La baja registral de un vehículo evita seguir pagando impuestos y seguros por un coche que ya no circula. La baja temporal impide circular por vía pública; la definitiva se tramita al entregar el vehículo a un centro de tratamiento de desguace autorizado (CAT).', 'vehiculos', 'estatal', 'Gratuito', '30 minutos', 'https://sede.dgt.gob.es'),
    ('Tarjeta de estacionamiento para personas con discapacidad', 'tarjeta-aparcamiento-discapacidad', 'Solicita la tarjeta de aparcamiento reservado para personas con movilidad reducida.', 'La tarjeta de estacionamiento para personas con discapacidad permite aparcar en plazas reservadas y en zonas con limitaciones de tiempo. La expiden los ayuntamientos previo reconocimiento de movilidad reducida y tiene validez en toda Europa.', 'vehiculos', 'estatal', 'Gratuito', '30 minutos', 'https://administracion.gob.es'),
    ('Consulta y pago de multas de tráfico', 'pago-multas-dgt', 'Consulta y paga tus multas de tráfico con descuento por pago voluntario.', 'Las sanciones de tráfico pueden consultarse y pagarse en la sede electrónica de la DGT. El pago voluntario en 20 días naturales reduce la multa un 50 %. Si no se paga en plazo, puede incrementarse y derivar en embargo o procedimientos de apremio.', 'vehiculos', 'estatal', 'Según la infracción (-50 % en pago voluntario)', '10 minutos', 'https://sede.dgt.gob.es'),
    ('Certificado de estar al corriente de obligaciones tributarias', 'certificado-corriente-aeat', 'Obtén el certificado de la AEAT que acredita estar al corriente con Hacienda.', 'El certificado de estar al corriente de pago o devuelto en período voluntario de las obligaciones tributarias lo emite la Agencia Tributaria. Es imprescindible para contratar con las administraciones públicas, licitaciones y muchas ayudas oficiales.', 'impuestos', 'estatal', 'Gratuito', '10 minutos (online e inmediato)', 'https://sede.agenciatributaria.gob.es'),
    ('Aplazamiento o fraccionamiento de deudas tributarias', 'aplazamiento-fraccionamiento-aeat', 'Solicita aplazar o fraccionar tus deudas con la Agencia Tributaria.', 'Si no puedes pagar una deuda tributaria en plazo, puedes solicitar su aplazamiento o fraccionamiento ante la AEAT. Con importes inferiores a 30.000 € no es necesario aportar garantías, aunque devenga intereses de demora (salvo situacionies específicas).', 'impuestos', 'estatal', 'Intereses de demora (sin garantías si < 30.000 €)', '20 minutos', 'https://sede.agenciatributaria.gob.es'),
    ('Devolución de ingresos indebidos a Hacienda', 'devolucion-ingresos-indebidos', 'Recupera pagos realizados de más a la AEAT con la solicitud de devolución.', 'Cuando has pagado un impuesto de más, lo has ingresado por duplicado o la deuda resultó inexistente, puedes solicitar la devolución de ingresos indebidos ante la AEAT. El plazo para solicitarla es de 4 años desde el ingreso.', 'impuestos', 'estatal', 'Gratuito', '15 minutos', 'https://sede.agenciatributaria.gob.es'),
    ('Consulta del valor catastral y certificación del Catastro', 'valor-catastral-catastro', 'Consulta el valor catastral de tu inmueble y solicita certificaciones oficiales.', 'El valor catastral es la referencia administrativa de los inmuebles que sirve para calcular el IBI y otros impuestos. Se puede consultar gratis en la Sede Electrónica del Catastro con la referencia catastral, y solicitar certificaciones oficiales del inmueble.', 'impuestos', 'estatal', 'Gratuito (consulta) - certificación según tarifa', '10 minutos', 'https://sedecatastro.oacc.es'),
    ('NIF para extranjeros con fines tributarios (AEAT)', 'nif-tributario-extranjeros', 'Obtén el NIF de persona física extranjera sin NIE para obligaciones fiscales.', 'Las personas extranjeras que no residan en España pero tengan obligaciones fiscales (por ejemplo, ser propietarios o heredar bienes) pueden solicitar un NIF de persona física sin NIE ante la Agencia Tributaria, necesario para presentar impuestos y firmezas.', 'impuestos', 'estatal', 'Gratuito', '20 minutos', 'https://sede.agenciatributaria.gob.es'),
    ('Admisión en centros de Educación Infantil y Primaria', 'admision-centros-infantil-primaria', 'Participa en el proceso de admisión escolar: plazos, baremo y documentación.', 'El proceso de admisión en centros públicos y concertados de Infantil y Primaria se realiza cada año en la comunidad autónoma de residencia. Las solicitudes se valoran con un baremo (renta, hermanos en el centro, proximidad) y se asignan plazas según la puntuación.', 'educacion', 'estatal', 'Gratuito', '30 minutos (en el periodo de admisión)', 'https://administracion.gob.es'),
    ('Ayudas para libros de texto y material didáctico', 'ayudas-material-didactico', 'Solicita las ayudas oficiales para libros de texto y material escolar.', 'El Ministerio y las comunidades autónomas convocan ayudas para la adquisición de libros de texto y material didáctico para alumnado de Primaria, ESO y ciclos formativos, con criterios de renta familiar y rendimiento escolar.', 'educacion', 'estatal', 'Gratuito', '20 minutos', 'https://www.educacionfpydeportes.gob.es'),
    ('Homologación de títulos extranjeros no universitarios', 'homologacion-titulos-extranjeros', 'Homologa tu título extranjero de educación no universitaria al sistema español.', 'La homologación equipara un título extranjero de educación no universitaria (bachillerato, FP) al título español correspondiente. La tramita el Ministerio de Educación y permite acceder a estudios, empleos y oposiciones con el título homologado.', 'educacion', 'estatal', 'Gratuito', '30 minutos (resolución en meses)', 'https://sede.educacion.gob.es'),
    ('Pruebas libres para la obtención del Graduado en ESO', 'pruebas-libres-eso', 'Obtén el título de Graduado en ESO mediante pruebas libres para adultos.', 'Las personas mayores de 18 años (o 16 en casos excepcionales) que no obtuvieron el Graduado en ESO pueden presentarse a pruebas libres convocadas por las comunidades autónomas. Superarlas permite obtener el título oficial y continuar estudios de Bachillerato o FP.', 'educacion', 'estatal', 'Gratuito', '20 minutos (inscripción)', 'https://administracion.gob.es'),
    ('Solicitud del título oficial de Bachiller', 'titulo-bachiller', 'Tramita el título oficial de Bachiller tras superar la etapa en tu comunidad.', 'El título de Bachiller se obtiene al superar la etapa (2 cursos) y lo expide la comunidad autónoma donde se cursaron los estudios. Es requisito para acceder a la universidad (junto a la EBAU) y a los ciclos formativos de grado superior.', 'educacion', 'estatal', 'Gratuito', '20 minutos', 'https://www.educacionfpydeportes.gob.es'),
    ('Primera expedición de la Tarjeta de Identidad de Extranjero (TIE)', 'primera-expedicion-tie', 'Obtén tu TIE tras conseguir tu autorización de residencia: cita, tasa y huellas.', 'La Tarjeta de Identidad de Extranjero (TIE) acredita la situación legal y la identidad de los extranjeros con autorización de residencia superior a 6 meses. Debe solicitarse en el plazo de un mes desde la entrada o la concesión de la autorización.', 'extranjeria', 'estatal', '19,45 € (tasa modelo 790 código 012)', '45 minutos (con cita previa)', 'https://icp.administracionelectronica.gob.es'),
    ('Renovación de la autorización de residencia temporal', 'renovacion-residencia-temporal', 'Renueva tu residencia temporal 60 días antes de su caducidad: requisitos y plazos.', 'Las autorizaciones de residencia temporal se renuevan durante los 60 días previos a la caducidad (o dentro de los 90 días posteriores, con posible sanción). La renovación exige acreditar los requisitos iniciales, como medios económicos y cotizaciones si procede.', 'extranjeria', 'estatal', 'Tasa modelo 790 código 052 (según modalidad)', '30 minutos', 'https://sede.administracionespublicas.gob.es'),
    ('Autorización de residencia por arraigo social', 'arraigo-social', 'Solicita el arraigo social: residencia temporal para inmigrantes consolidados.', 'El arraigo social permite obtener una autorización de residencia temporal a extranjeros que llevan al menos 2 años en España (sin ser residentes legales), acreditan medios económicos y cuentan con un contrato de trabajo o informes favorables de arraigo.', 'extranjeria', 'estatal', 'Tasa modelo 790 código 052', '30 minutos', 'https://sede.administracionespublicas.gob.es'),
    ('Autorización de trabajo por cuenta ajena (régimen general)', 'autorizacion-trabajo-cuenta-ajena', 'Tramita la autorización inicial de trabajo por cuenta ajena para extranjeros.', 'Los extranjeros no residentes legalmente en España necesitan una autorización de trabajo por cuenta ajena para ser contratados. La solicita el empleador ante la oficina de extranjería, justificando la situación nacional de empleo y el contrato de trabajo.', 'extranjeria', 'estatal', 'Tasa modelo 790 (código 052/053 según régimen)', '30 minutos', 'https://sede.administracionespublicas.gob.es'),
    ('Nacionalidad española por residencia', 'nacionalidad-espanola-residencia', 'Solicita la nacionalidad española tras 10 años de residencia legal y continua.', 'La nacionalidad española por residencia requiere 10 años de residencia legal, continuada e inmediatamente anterior a la solicitud (5 para refugiados, 2 para iberoamericanos y otros supuestos, 1 para casados con español). Se tramita ante el Ministerio de Justicia.', 'extranjeria', 'estatal', 'Tasa modelo 107', '30 minutos (pruebas DELE/CCSE aparte)', 'https://sede.mjusticia.gob.es'),
    ('Visado de estancia por estudios (visado de estudios)', 'visado-estudios', 'Solicita el visado de estudios para cursar programas en España (más de 90 días).', 'El visado de estancia por estudios habilita a extranjeros no comunitarios a permanecer en España para realizar estudios, formación, investigación o intercambio por más de 90 días. Se solicita en el consulado español del país de residencia del interesado.', 'extranjeria', 'estatal', 'Tasa consular según nacionalidad (aprox. 80 €)', '1 hora (resolución en semanas)', 'https://www.exteriores.gob.es'),
    ('Certificado de eficiencia energética de vivienda', 'certificado-eficiencia-energetica', 'Obtén el certificado de eficiencia energética obligatorio para vender o alquilar.', 'El certificado de eficiencia energética (CEE) valora el consumo de energía de una vivienda y es obligatorio para venderla o alquilarla. Lo emiten técnicos cualificados y se registra en el organismo autonómico correspondiente.', 'vivienda', 'estatal', 'Aprox. 100-300 € (según vivienda y técnico)', '1-2 horas de visita técnica', 'https://administracion.gob.es'),
    ('Cédula de habitabilidad', 'cedula-habitabilidad', 'Tramita la cédula de habitabilidad, documento obligatorio en varias comunidades.', 'La cédula de habitabilidad acredita que una vivienda cumple las condiciones mínimas de habitabilidad (superficie, instalaciones, salubridad). Es obligatoria para ocupar la vivienda y para contratar suministros en comunidades como Cataluña o Baleares.', 'vivienda', 'estatal', 'Tasa autonómica (aprox. 15-100 €)', '30 minutos (resolución en semanas)', 'https://administracion.gob.es'),
    ('Inscripción en programas de Vivienda de Protección Oficial (VPO)', 'inscripcion-vpo', 'Inscríbete en el registro de solicitantes de vivienda de protección oficial.', 'Para optar a una vivienda de protección oficial (VPO) en venta, alquiler o cesión, hay que inscribirse en el registro de demandantes de vivienda protegida de la comunidad autónoma o municipio. Los ingresos familiares y la situación determinan la elegibilidad.', 'vivienda', 'estatal', 'Gratuito', '30 minutos', 'https://administracion.gob.es'),
    ('Aplazamiento de hipoteca por dificultades (Código de Buenas Prácticas)', 'aplazamiento-hipoteca-cbp', 'Solicita la carencia o reestructuración de tu hipoteca si estás en riesgo.', 'Los deudores hipotecarios en dificultades pueden acogerse a los Códigos de Buenas Prácticas y medidas extraordinarias: carencia de capital, reducción temporal del tipo o quita en el caso de resolución. Se solicita directamente en el banco, con protocolo de reclamación al servicio de atención al cliente y al Banco de España si se deniega.', 'vivienda', 'estatal', 'Gratuito (sujeto a condiciones del código aplicable)', '30 minutos', 'https://www.bde.es'),
    ('Licencia de primera ocupación de vivienda', 'licencia-primera-ocupacion', 'Tramita la licencia de primera ocupación para estrenar vivienda legalmente.', 'La licencia de primera ocupación (o cédula, según la comunidad) acredita que una vivienda de nueva construcción cumple los requisitos para ser habitada. Es imprescindible para contratar suministros, empadronarse y, en muchos casos, para la compraventa.', 'vivienda', 'estatal', 'Tasa municipal o autonómica (aprox. 50-200 €)', '30 minutos (resolución en semanas)', 'https://administracion.gob.es'),
    ('Nota simple registral de una vivienda', 'nota-simple-registral', 'Solicita la nota simple del Registro de la Propiedad: titularidad y cargas.', 'La nota simple es un documento informativo del Registro de la Propiedad que refleja la titularidad, descripción y cargas (hipotecas, embargos) de un inmueble. Es imprescindible antes de comprar una vivienda para conocer su situación jurídica real.', 'vivienda', 'estatal', 'Aprox. 9-15 € (online)', '10 minutos (entrega en 24-48 h)', 'https://www.registradores.org'),
    ('Certificado de disponibilidad de denominación social', 'certificado-denominacion-social', 'Reserva el nombre de tu empresa en el Registro Mercantil antes de constituirla.', 'La certificación negativa de denominación social acredita que el nombre elegido para tu empresa no está registrado. Es el primer paso para constituir una sociedad (SL, SA) y tiene una vigencia de 3 meses desde su expedición.', 'empresas', 'estatal', 'Aprox. 15 €', '15 minutos (resolución en 24-72 h)', 'https://www.registradores.org'),
    ('Constitución de una Sociedad Limitada (SL)', 'constitucion-sociedad-limitada', 'Crea tu Sociedad Limitada: escritura notarial, inscripción y tasas.', 'La Sociedad Limitada es la forma jurídica más habitual para empresas en España. Su constitución exige el certificado de denominación, la escritura notarial con los estatutos y socios, el depósito del capital social (desde 1 €) y la inscripción en el Registro Mercantil.', 'empresas', 'estatal', 'Tasas notariales y registrales (aprox. 300-600 €)', '1-2 semanas', 'https://www.registradores.org'),
    ('Inscripción de la empresa en la Seguridad Social (cuenta de cotización)', 'cuenta-cotizacion-empresa', 'Abre la cuenta de cotización de tu empresa para contratar trabajadores.', 'Toda empresa que vaya a contratar trabajadores debe inscribirse en la Seguridad Social, obteniendo un Código de Cuenta de Cotización (CCC). Es el paso previo obligatorio al alta de los empleados y se tramita en la Tesorería General de la Seguridad Social (TGSS).', 'empresas', 'estatal', 'Gratuito', '20 minutos', 'https://sede.seg-social.gob.es'),
    ('Comunicación de contratos de trabajo (Sistema Contrat@)', 'comunicacion-contratos-contrat', 'Registra los contratos de tus trabajadores en el sistema Contrat@ del SEPE.', 'Las empresas deben comunicar al Servicio Público de Empleo Estatal (SEPE) el contenido de los contratos de trabajo que formalicen, mediante el sistema Contrat@, en los 10 días siguientes a su firma. Es obligatorio y gratuito.', 'empresas', 'estatal', 'Gratuito', '15 minutos', 'https://sede.sepe.gob.es'),
    ('Inscripción de la sociedad en el Registro Mercantil', 'registro-mercantil-sociedad', 'Inscribe tu sociedad en el Registro Mercantil para adquirir plena personalidad.', 'La inscripción en el Registro Mercantil otorga a la sociedad su plena eficacia jurídica frente a terceros. Se presenta la escritura de constitución (o actos posteriores: ampliaciones, cambios de órgano, disolución) en el Registro Mercantil Provincial correspondiente.', 'empresas', 'estatal', 'Tasa registral (según capital, aprox. 150-400 €)', '20 minutos (resolución en 15 días)', 'https://www.registradores.org'),
    ('Reclamación en materia de consumo', 'reclamacion-consumo', 'Reclama ante las autoridades de consumo por productos o servicios defectuosos.', 'Cuando una empresa no responde a tus quejas sobre un producto o servicio (compras, telecomunicaciones, energía, reparaciones), puedes presentar una reclamación en las oficinas municipales o autonómicas de consumo, preferiblemente con la hoja de reclamaciones oficial.', 'consumo', 'estatal', 'Gratuito', '20 minutos', 'https://consumo.gob.es'),
    ('Reclamación ante la Agencia Española de Protección de Datos (AEPD)', 'reclamacion-aepd', 'Denuncia a la AEPD usos indebidos de tus datos personales o spam persistente.', 'Si una empresa usa tus datos personales sin consentimiento, no atiende tu solicitud de baja, o te envía publicidad tras oponerte, puedes reclamar a la AEPD. Primero debe reclamarse a la empresa responsable y, si no responde en un mes, presentar la reclamación.', 'consumo', 'estatal', 'Gratuito', '20 minutos', 'https://sedeagpd.gob.es'),
    ('Reclamación por cancelación, retraso o pérdida de equipaje (AESA)', 'reclamacion-vuelos-aesa', 'Reclama tus derechos como pasajero aéreo ante AESA: compensaciones y asistencia.', 'Ante cancelaciones, grandes retrasos (más de 3 horas a la llegada), denegación de embarque o pérdida de equipaje, los pasajeros tienen derechos en la UE (Reglamento 261/2004). Si la aerolínea no responde o deniega la compensación, puedes reclamar a la Agencia Estatal de Seguridad Aérea (AESA).', 'consumo', 'estatal', 'Gratuito', '20 minutos', 'https://www.seguridadaerea.gob.es'),
    ('Inscripción en la Lista Robinson', 'lista-robinson', 'Date de alta en la Lista Robinson para no recibir publicidad no deseada.', 'La Lista Robinson es el sistema de exclusión publicitaria gestionado por la Federación de Comercio Electrónico y Marketing Directo. Al inscribirte, las empresas adheridas dejan de enviarte publicidad postal, telefónica o por email si no tienen tu consentimiento expreso.', 'consumo', 'estatal', 'Gratuito', '10 minutos', 'https://www.listarobinson.es'),
    ('Reclamación ante el Banco de España por servicios financieros', 'reclamacion-banco-espana', 'Reclama al Banco de España contra tu banco por comisiones o malas prácticas.', 'Si tu banco rechaza o ignora tu reclamación sobre comisiones, hipoteca, tarjetas u otros servicios, puedes acudir al Departamento de Conducta de Entidades del Banco de España. Es necesario haber reclamado primero al Servicio de Atención al Cliente del banco.', 'consumo', 'estatal', 'Gratuito', '20 minutos', 'https://reclamaciones.bde.es'),
    ('Solicitud de arbitraje de consumo', 'arbitraje-consumo', 'Resuelve conflictos de consumo de forma rápida y gratuita mediante arbitraje.', 'El arbitraje de consumo es un sistema gratuito y ágil para resolver conflictos con empresas adheridas a las juntas arbitrales de consumo, sin necesidad de ir a los tribunales. El laudo arbitral es vinculante para ambas partes.', 'consumo', 'estatal', 'Gratuito', '20 minutos', 'https://consumo.gob.es')
) AS v(title, slug, short_description, descr, cat_slug, scope, cost, duration, url)
JOIN public.procedure_categories c ON c.slug = v.cat_slug
WHERE NOT EXISTS (SELECT 1 FROM public.procedures p WHERE p.slug = v.slug);

