    ('constitucion-sociedad-limitada', 'Registro Mercantil', 'https://www.registradores.org', 'official'),
    ('cuenta-cotizacion-empresa', 'Seguridad Social - Sede electrónica', 'https://sede.seg-social.gob.es', 'official'),
    ('comunicacion-contratos-contrat', 'SEPE - Contrat@', 'https://sede.sepe.gob.es', 'official'),
    ('registro-mercantil-sociedad', 'Registro Mercantil', 'https://www.registradores.org', 'official'),
    ('reclamacion-consumo', 'Agencia Española de Consumo', 'https://consumo.gob.es', 'official'),
    ('reclamacion-aepd', 'AEPD - Sede electrónica', 'https://sedeagpd.gob.es', 'official'),
    ('reclamacion-vuelos-aesa', 'AESA - Derechos de los pasajeros', 'https://www.seguridadaerea.gob.es', 'official'),
    ('lista-robinson', 'Lista Robinson', 'https://www.listarobinson.es', 'official'),
    ('reclamacion-banco-espana', 'Banco de España - Reclamaciones', 'https://reclamaciones.bde.es', 'official'),
    ('arbitraje-consumo', 'Agencia Española de Consumo', 'https://consumo.gob.es', 'official')
) AS v(slug, title, url, ltype)
JOIN public.procedures p ON p.slug = v.slug
WHERE NOT EXISTS (SELECT 1 FROM public.procedure_links l WHERE l.procedure_id = p.id AND l.url = v.url);

COMMIT;
